CREATE TABLE IF NOT EXISTS account (id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, join_code TEXT NOT NULL, restrict_rooms INTEGER NOT NULL DEFAULT 0, custom_css TEXT NOT NULL DEFAULT '', logo_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT COLLATE NOCASE UNIQUE, password TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','administrator','bot')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','deactivated','banned')), avatar_id INTEGER NOT NULL DEFAULT 0, bot_key TEXT UNIQUE, webhook TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, ip TEXT NOT NULL, agent TEXT NOT NULL, created_at INTEGER NOT NULL, active_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS transfers (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bans (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, ip TEXT NOT NULL, PRIMARY KEY(user_id,ip));
CREATE INDEX IF NOT EXISTS bans_ip ON bans(ip);
CREATE TABLE IF NOT EXISTS rooms (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('open','closed','direct')), creator_id INTEGER NOT NULL REFERENCES users(id), direct_key TEXT UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, involvement TEXT NOT NULL DEFAULT 'mentions' CHECK(involvement IN ('invisible','nothing','mentions','everything')), read_id INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(room_id,user_id));
CREATE INDEX IF NOT EXISTS memberships_user ON memberships(user_id,room_id);
CREATE TABLE IF NOT EXISTS uploads (id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id INTEGER NOT NULL REFERENCES users(id), key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, thumb TEXT NOT NULL DEFAULT '', width INTEGER NOT NULL DEFAULT 0, height INTEGER NOT NULL DEFAULT 0, duration REAL NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id), client_id TEXT NOT NULL, body TEXT NOT NULL, plain TEXT NOT NULL, upload_id INTEGER REFERENCES uploads(id), reply_id INTEGER REFERENCES messages(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id,client_id));
CREATE INDEX IF NOT EXISTS messages_room ON messages(room_id,id);
CREATE INDEX IF NOT EXISTS messages_user ON messages(user_id);
CREATE INDEX IF NOT EXISTS messages_upload ON messages(upload_id);
CREATE TABLE IF NOT EXISTS link_previews (message_id INTEGER PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE, url TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, image_id INTEGER REFERENCES uploads(id));
CREATE VIRTUAL TABLE IF NOT EXISTS message_fts USING fts5(body, tokenize='unicode61');
CREATE TABLE IF NOT EXISTS mentions (message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(message_id,user_id));
CREATE TABLE IF NOT EXISTS boosts (id INTEGER PRIMARY KEY AUTOINCREMENT, message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id), content TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS boosts_message ON boosts(message_id);
CREATE TABLE IF NOT EXISTS searches (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, query TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(user_id,query));
CREATE TABLE IF NOT EXISTS subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_token TEXT NOT NULL REFERENCES sessions(token) ON DELETE CASCADE, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, agent TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at INTEGER NOT NULL, locked_at INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(available_at,locked_at);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0, reset_at INTEGER NOT NULL);
PRAGMA user_version=1;
